package com.hrm.service;
import java.time.*;import java.util.*;import java.security.Principal;
import com.hrm.dto.EmployeeRequestDTOs.Rejection;
import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class LeaveCancellationTest {
 JdbcTemplate db;PersonnelAccessService access;PersonnelWorkflowSupport support;AssignmentGuardService timeline;EmployeeRequestService service;LeaveRequestRules rules;PersonnelScopeService scope;RequestApprovalStages stages;Principal p=()->"user";LocalDateTime now=LocalDateTime.of(2026,11,8,12,0);
 @BeforeEach void setup(){db=mock(JdbcTemplate.class);access=mock(PersonnelAccessService.class);support=mock(PersonnelWorkflowSupport.class);timeline=mock(AssignmentGuardService.class);rules=mock(LeaveRequestRules.class);scope=mock(PersonnelScopeService.class);stages=mock(RequestApprovalStages.class);service=new EmployeeRequestService(db,access,support,timeline);ReflectionTestUtils.setField(service,"leaveRules",rules);ReflectionTestUtils.setField(service,"personnelScope",scope);ReflectionTestUtils.setField(service,"approvalStages",stages);when(support.localNow()).thenReturn(now);when(access.actor(p)).thenReturn(new PersonnelAccessService.Actor(5,70,"EMPLOYEE"));}
 Map<String,Object> row(String status){return new HashMap<>(Map.of("requestId",4L,"employeeId",70L,"requestType","NGHI_PHEP","status",status,"leaveStart",now.plusDays(1).toString(),"leaveEnd",now.plusDays(1).plusHours(4).toString()));}
 void rows(Map<String,Object> before){var after=new HashMap<>(before);after.put("status","DA_HUY");after.put("withdrawnAt",now.toString());when(db.queryForList(contains("r.request_id=? AND"),eq(4L))).thenReturn(List.of(before),List.of(after));when(db.queryForList(contains("SELECT employment_status"),eq(String.class),eq(70L))).thenReturn(List.of("DANG_LAM"));}
 @Test void policyRejectsStartedRejectedAndAlreadyCancelled(){assertNull(LeaveCancellationPolicy.blocker("NGHI_PHEP","CHO_DUYET",false,now.plusMinutes(1),now));assertNotNull(LeaveCancellationPolicy.blocker("NGHI_PHEP","CHO_DUYET",false,now,now));assertNotNull(LeaveCancellationPolicy.blocker("NGHI_PHEP","TU_CHOI",false,now.plusDays(1),now));assertNotNull(LeaveCancellationPolicy.blocker("NGHI_PHEP","DA_DUYET",true,now.plusDays(1),now));}
 @Test void ownerCancelsApprovedLeaveWithAuditAndMutableCheck(){var before=row("DA_DUYET");rows(before);var result=service.cancelLeave(4,new Rejection("Đổi kế hoạch"),p);assertEquals("DA_HUY",result.get("status"));assertEquals(false,result.get("canCancelLeave"));verify(rules).requireMutable(70,now.plusDays(1),now.plusDays(1).plusHours(4));verify(support).audit(eq(5L),eq("LEAVE_REQUEST_CANCEL"),eq("employee_requests"),eq(4L),eq("Đổi kế hoạch"),eq(before),any());verify(timeline).lockTimeline();}
 @Test void lockedPeriodBlocksCancellationBeforeWithdrawal(){rows(row("DA_DUYET"));doThrow(new ResponseStatusException(HttpStatus.CONFLICT,"Kỳ đã khóa")).when(rules).requireMutable(anyLong(),any(),any());assertThrows(ResponseStatusException.class,()->service.cancelLeave(4,new Rejection("Test"),p));verify(db,never()).update(contains("INSERT dbo.employee_request_withdrawals"),any(Object[].class));}
 @Test void headCannotCancelFinalApprovalForOthers(){rows(row("DA_DUYET"));when(access.actor(p)).thenReturn(new PersonnelAccessService.Actor(5,50,"EMPLOYEE"));when(stages.canRead(70,p)).thenReturn(true);assertEquals(409,assertThrows(ResponseStatusException.class,()->service.cancelLeave(4,new Rejection("Test"),p)).getStatusCode().value());}
 @Test void headCanCancelPendingWithinDepartment(){rows(row("CHO_DUYET"));when(access.actor(p)).thenReturn(new PersonnelAccessService.Actor(5,50,"EMPLOYEE"));when(stages.canRead(70,p)).thenReturn(true);assertEquals("DA_HUY",service.cancelLeave(4,new Rejection("Nhân viên gửi nhầm"),p).get("status"));}
 @Test void outsideScopeAndEmptyReasonAreDenied(){rows(row("CHO_DUYET"));when(access.actor(p)).thenReturn(new PersonnelAccessService.Actor(5,50,"EMPLOYEE"));assertEquals(403,assertThrows(ResponseStatusException.class,()->service.cancelLeave(4,new Rejection("Test"),p)).getStatusCode().value());assertEquals(400,assertThrows(ResponseStatusException.class,()->service.cancelLeave(4,new Rejection(" "),p)).getStatusCode().value());}
}
